import{_ as e,a,o as r,a4 as s}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Products","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/products/index.md","filePath":"api/rest-api/shop/products/index.md","lastUpdated":1783420618000}'),o={name:"api/rest-api/shop/products/index.md"};function d(i,t,c,p,n,u){return r(),a("div",null,t[0]||(t[0]=[s('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>The Products menu is the catalog surface a shopper browses and searches. It returns product listings, full single-product detail, search results, booking slots for bookable products, and a set of sub-resources for the heavier data attached to a product (images, prices, attribute values, and type-specific structure).</p><h2 id="listing-search-and-detail" tabindex="-1">Listing, search and detail <a class="header-anchor" href="#listing-search-and-detail" aria-label="Permalink to &quot;Listing, search and detail&quot;">​</a></h2><ul><li>The <strong>list</strong> endpoint returns a paginated catalog with filtering, sorting and faceted attribute filters. <strong>Search</strong> is the same listing surface with a search term applied.</li><li>The <strong>single product</strong> endpoint returns one product&#39;s full detail, with its categories, images, variants and type-specific blocks embedded — no follow-up calls needed for the common fields.</li><li><strong>Booking slots</strong> return the available time slots for a bookable product.</li></ul><p>Pass <code>locale</code> and <code>channel</code> to receive catalog data for a specific language and store. Filters beyond the basics (price, category, type, new/featured) cover any filterable attribute the catalog exposes.</p><h2 id="sub-resources" tabindex="-1">Sub-resources <a class="header-anchor" href="#sub-resources" aria-label="Permalink to &quot;Sub-resources&quot;">​</a></h2><p>For data that is heavy or addressed on its own, products expose dedicated sub-resource endpoints (e.g. a variant&#39;s images, customer-group prices, attribute values, and the structure that varies by product type). The two sub-resource pages below describe what each one returns and when to call it instead of relying on the inlined detail.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/products/get-products.html">Products</a></td><td><code>GET /api/shop/products</code></td><td>Paginated, filterable, sortable product listing.</td></tr><tr><td><a href="/api/rest-api/shop/products/search-product.html">Search Products</a></td><td><code>GET /api/shop/products</code></td><td>The listing with a search term applied.</td></tr><tr><td><a href="/api/rest-api/shop/products/get-product.html">Single Product</a></td><td><code>GET /api/shop/products/{id}</code></td><td>Full detail for one product.</td></tr><tr><td><a href="/api/rest-api/shop/products/get-booking-slots.html">Booking Slots</a></td><td><code>GET /api/shop/booking-slots</code></td><td>Available slots for a bookable product.</td></tr><tr><td><a href="/api/rest-api/shop/products/product-subresources.html">Product Sub-Resources</a></td><td><code>GET /api/shop/products/{id}/…</code></td><td>Images, prices and attribute values per product.</td></tr><tr><td><a href="/api/rest-api/shop/products/product-type-subresources.html">Product Type Sub-Resources</a></td><td><code>GET /api/shop/products?type=…</code></td><td>Type-specific structure (configurable, bundle, etc.).</td></tr></tbody></table><p>All Product endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',10)]))}const b=e(o,[["render",d]]);export{h as __pageData,b as default};
